package br.com.sussmartcare.triage.infrastructure.projection; import jakarta.persistence.*; import java.time.*; import java.util.*; @Entity @Table(name="triage_observations") public class TriageObservation{@Id private UUID id;@Column(nullable=false)private UUID visitId;@Column(nullable=false)private String type;@Column(nullable=false)private double value;private String unit;@Column(nullable=false)private Instant measuredAt;protected TriageObservation(){}public TriageObservation(UUID id,UUID visit,String type,double value,String unit,Instant at){this.id=id;visitId=visit;this.type=type;this.value=value;this.unit=unit;measuredAt=at;}public String getType(){return type;}public double getValue(){return value;}public String getUnit(){return unit;}public Instant getMeasuredAt(){return measuredAt;}}
